(()=>{
const q=s=>document.querySelector(s), canvas=q('#magnetosphereCanvas'); if(!canvas)return;
const recent=[['٢١ أغسطس ٢٠٢٤','عاصفة شديدة بعد قذف كتلي إكليلي','G4','أحد أقوى الأحداث في الدورة الشمسية الحالية.'],['١٠–١٢ مايو ٢٠٢٤','عاصفة تاريخية خلال الدورة ٢٥','G5','وصل النشاط إلى مستويات نادرة وأنتج شفقًا في مناطق واسعة.'],['٢٣–٢٤ مارس ٢٠٢٣','عاصفة قوية متعددة المراحل','G4','تسببت في اضطرابات مغناطيسية وشفق على عروض جغرافية منخفضة نسبيًا.']];
const historic=[['١٣–١٥ مارس ١٩٨٩','عاصفة كيبيك','G5','أدت إلى انقطاع كهربائي واسع في كيبيك.'],['٢–٤ أغسطس ١٩٧٢','عاصفة شمسية سريعة','G5','حدثت بين بعثتي أبولو ١٦ و١٧ وكادت تكون خطرة على الرحلات المأهولة.'],['١–٢ سبتمبر ١٨٥٩','حدث كارينغتون','G5','من أشهر العواصف المسجلة تاريخيًا، قبل عصر الأقمار الصناعية.']];
let storm=28, mode='quiet', playing=true, raf=0, yaw=0;
function fmt(n){return n==null?'—':String(Math.round(n*10)/10).replace('.', '٫').replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);}
function draw(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1,w=Math.max(1,r.width),h=Math.max(1,r.height);canvas.width=w*d;canvas.height=h*d;const c=canvas.getContext('2d');c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,w,h);const cx=w*.38+Math.sin(yaw)*w*.025,cy=h*.53,earth=Math.min(w,h)*.055, s=1+storm/150; c.save();c.translate(cx,cy);
 c.fillStyle='rgba(85,216,242,.05)';c.beginPath();c.ellipse(w*.16,0,w*.32*s,h*.35*s,0,0,Math.PI*2);c.fill();
 for(let i=0;i<13;i++){const yy=(i-6)*h*.045, bend=(i-6)*w*.018*s;c.beginPath();c.moveTo(-w*.5,yy*.55);c.bezierCurveTo(-w*.27,yy-bend,-w*.08,yy*.25,w*.04,yy*.02);c.bezierCurveTo(w*.2,yy*.4,w*.42,yy+bend,w*.72,yy*1.35);c.strokeStyle=`rgba(${mode==='storm'?255:85},${mode==='storm'?100:216},242,${.28+((i%3)*.09)})`;c.lineWidth=1.1+(i%3)*.35;c.stroke();}
 for(let i=0;i<9;i++){const a=(i/9)*Math.PI*2+Math.sin(yaw)*.3;c.beginPath();c.moveTo(Math.cos(a)*earth*1.1,Math.sin(a)*earth*1.1);c.bezierCurveTo(Math.cos(a)*earth*2,Math.sin(a)*earth*2,Math.cos(a)*w*.2,Math.sin(a)*h*.24,w*.67,Math.sin(a)*h*.26);c.strokeStyle='rgba(83,157,255,.38)';c.lineWidth=1;c.stroke();}
 const g=c.createRadialGradient(-earth*.35,-earth*.4,1,0,0,earth*1.5);g.addColorStop(0,'#ffe59a');g.addColorStop(.45,'#f5a84d');g.addColorStop(1,'#b94c38');c.fillStyle=g;c.shadowColor='#ffb74e';c.shadowBlur=24;c.beginPath();c.arc(0,0,earth,0,Math.PI*2);c.fill();c.shadowBlur=0;c.strokeStyle='rgba(255,255,255,.5)';c.stroke();c.restore();
 if(playing){yaw+=.003;raf=requestAnimationFrame(draw)}}
function render(list){q('#magStormList').innerHTML=list.map(x=>`<article class="mag-storm-item"><time>${x[0]}</time><div><b>${x[1]}</b><p>${x[3]}</p></div><em>${x[2]}</em></article>`).join('')}
function setStorm(v){storm=+v;mode=storm>62?'storm':'quiet';q('#magStormValue').textContent=storm>70?'شديدة':storm>42?'نشطة':'هادئة';q('#magExplainTitle').textContent=storm>62?'انضغاط واضح أثناء العاصفة':'غلاف مضغوط طبيعيًا';q('#magExplainText').textContent=storm>62?'يزداد ضغط الرياح الشمسية، فتتقلص الجهة المواجهة للشمس ويزداد اضطراب الذيل المغناطيسي.':'تدفع الرياح الشمسية خطوط المجال نحو الجهة المواجهة للشمس، وتمتد خلف الأرض في ذيل مغناطيسي طويل.';draw()}
async function live(){try{const [m,k,f]=await Promise.all([fetch('https://services.swpc.noaa.gov/products/summary/solar-wind-mag-field.json').then(r=>r.json()),fetch('https://services.swpc.noaa.gov/products/noaa-planetary-k-index-forecast.json').then(r=>r.json()),fetch('https://services.swpc.noaa.gov/products/summary/solar-wind-speed.json').then(r=>r.json())]);const mag=m.at(-1),kp=k.at(-1),speed=f.at(-1);const bt=Number(mag?.[3]),kpv=Number(kp?.[1]),sp=Number(speed?.[2]);if(Number.isFinite(kpv)){q('#magKp').textContent=fmt(kpv);q('#magKpLabel').textContent=kpv>=5?'نشاط عاصفي':'هادئ إلى نشط';setStorm(Math.min(100,kpv*10))}if(Number.isFinite(bt))q('#magBt').textContent=fmt(bt);if(Number.isFinite(sp))q('#magPressure').textContent=fmt(Math.max(0,sp/430)**2*1.6);q('#magLiveLabel').textContent='بيانات حية';q('#magUpdatedAt').textContent='آخر قياس من SWPC';q('#magSourceStatus').textContent='متصل بمركز NOAA/SWPC';}catch(e){q('#magLiveLabel').textContent='وضع العرض المحلي';q('#magUpdatedAt').textContent='تتعذر قراءة المصدر الآن';q('#magSourceStatus').textContent='السجل المحلي يعمل دون اتصال'} }
function activate(){render(recent);q('#magStormRange').value=storm;draw();live();clearInterval(window.__magTimer);window.__magTimer=setInterval(live,300000)}
q('#magStormRange').oninput=e=>setStorm(e.target.value);q('#magPlay').onclick=e=>{playing=!playing;e.currentTarget.textContent=playing?'Ⅱ إيقاف الحركة':'▶ تشغيل الحركة';if(playing)draw();else cancelAnimationFrame(raf)};q('#magStage')?.addEventListener('pointermove',e=>{if(e.buttons)yaw+=e.movementX*.01});q('#magnetosphereCanvas').addEventListener('pointermove',e=>{if(e.buttons){yaw+=e.movementX*.01;draw()}});q('#magnetosphereCanvas').addEventListener('wheel',e=>{e.preventDefault();storm=Math.max(0,Math.min(100,storm-e.deltaY*.05));q('#magStormRange').value=storm;setStorm(storm)},{passive:false});document.querySelectorAll('[data-mag-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mag-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');setStorm(b.dataset.magView==='storm'?78:28)});document.querySelectorAll('[data-mag-record]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mag-record]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.magRecord==='historic'?historic:b.dataset.magRecord==='forecast'?[['الأيام القادمة','توقع SWPC يتغير مع الرصد','—','اضغط تحديث البيانات عند فتح التبويب لرؤية أحدث توقع.']]:recent)});addEventListener('resize',draw);window.magnetosphere={activate};})();
